// =======================
// 系統事件（Supabase / internal webhook）
// ⚠️ 保留，不動、不加 event_id
// =======================
if ($json.body?.source === "system") {
  return {
    source: "system",
    payload: $json.body
  };
}

// =======================
// LINE webhook 使用者事件
// =======================
const events = $json.body?.events || [];

const event = events.find(
  (e) =>
    e.type === "message" &&
    (e.message?.type === "text" || e.message?.type === "image") &&
    e.source?.userId
);

if (event) {
  const event_id =
    event.eventId ||
    `${event.source.userId}-${event.timestamp}-${event.message?.id || "no-msg"}`;

  return {
    source: "user",
    event_id,
    line_user_id: event.source.userId,
    message_type: event.message.type,
    user_text: event.message.type === "text" ? event.message.text : null,
    message_id: event.message.id,
    event_timestamp: event.timestamp
  };
}

return {
  source: "ignore",
  event_types: events.map(e => e.type)
};

/**
 * n8n Code Node
 * 重組 LINE 訂單通知訊息（完整版、安全版）
 */

if ($json.source && $json.source !== "system") {
  return { source: "ignore" };
}

const {
  order_id,
  order_status,
  status_message,
  product_summary,
  expected_pickup_date,
  notes,
  total_amount,
  line_user_id,
  user_name
} = $json;

const name =
  user_name && user_name.trim() !== ""
    ? user_name
    : "親愛的顧客";

const statusMap = {
  awaiting_payment: "訂單待付款",
  payment_submitted: "已收到款項",
  processing: "甜點正在製作中",
  shipped: "甜點已完成，準備出貨",
  delivered: "甜點已出貨",
  completed: "訂單已完成",
  canceled: "訂單已取消",
  returned: "訂單已退款"
};

const statusText =
  (status_message && status_message.trim() !== "" && status_message) ||
  statusMap[order_status] ||
  "訂單狀態已更新";

const line = (label, value) =>
  value !== undefined &&
  value !== null &&
  value !== ""
    ? `\n${label}：${value}`
    : "";

const message = `🍰 T&J 訂單通知
━━━━━━━━━━━━
${name} 您好 👋

訂單編號：${order_id || "—"}
狀態更新：${statusText}
${line("品項內容", product_summary)}
${line("取貨日期", expected_pickup_date)}
${line("訂單金額", total_amount !== null ? `$${total_amount}` : "")}
${line("備註事項", notes)}
━━━━━━━━━━━━
如有任何問題，歡迎直接回覆本訊息與我們聯繫 💬
`;

return {
  line_user_id,
  reply_text: message
};

// 只處理 system
if ($json.source !== "system") {
  return { source: "ignore" };
}

const data =
  $json.payload?.payload ||
  $json.payload ||
  null;

if (!data) {
  return { source: "ignore" };
}

return {
  source: "system",
  line_user_id: data.line_user_id || null,
  email: data.customer_email || data.user_email || null,
  order_id: data.order_id,
  order_status: data.order_status || null,
  total_amount:
    data.total_amount ??
    data.TradeAmt ??
    null,
  product_summary:
    data.product_summary ||
    data.product_summury ||
    "",
  expected_pickup_date:
    data.expected_pickup_date ??
    data.pickup_date ??
    data.expected_delivery_date ??
    data.delivery_date ??
    null,
  shipping_way:
    data.shipping_way ||
    null,
  notes:
    data.notes ||
    data.note ||
    null,
  status_message: data.status_message || null
};

const adminIds = [
"Ue6499ae132e994266ea500b976a3277c",
  "U7fb743a941f0e5574a21b4c5686585e8"
];

const raw = $input.first().json;
const body = raw.payload?.payload || raw.payload || raw;

const recipientName = body.who_receive || "（未知客戶）";

const message = `已收到${recipientName}的轉帳，請到後台點擊收到款項（查帳後）`;

return adminIds.map(id => ({
